import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"43、【夬】 乾下兑上","description":"周易口诀义 - 43、【夬】 乾下兑上","frontmatter":{"title":"43、【夬】 乾下兑上","description":"周易口诀义 - 43、【夬】 乾下兑上"},"headers":[],"relativePath":"zh/classics/koujueyi/045.md","filePath":"zh/classics/koujueyi/045.md"}'),r={name:"zh/classics/koujueyi/045.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_43、【夬】-乾下兑上" tabindex="-1">43、【夬】 乾下兑上 <a class="header-anchor" href="#_43、【夬】-乾下兑上" aria-label="Permalink to “43、【夬】 乾下兑上”">​</a></h1><p>彖曰：「夬」，决也，刚决柔也。健而说，决而和。「扬于王庭」，柔乘五刚也；「孚号有厉」，其危乃光也；「告自邑，不利即戎」，所尚乃穷也；「利有攸往」，刚长乃终也。</p><p>象曰：泽上于天，夬；君子以施禄及下，居德则忌。</p><p>初九，壮于前趾，往不胜为咎。</p><p>象曰：不胜而往，咎也。</p><p>九二，惕号，莫夜有戎，勿恤。</p><p>象曰：「有戎勿恤」，得中道也。</p><p>九三，壮于𬱓，有凶。君子夬夬独行，遇雨若濡有愠，无咎。</p><p>象曰：「君子夬夬」，终无咎也。</p><p>九四，臀无肤，其行次且。牵羊悔亡，闻言不信。</p><p>象曰：「其行次且」，位不当也。「闻言不信」，聪不明也。</p><p>九五，苋陆夬夬，中行无咎。</p><p>象曰：「中行无咎」，中未光也。</p><p>上六，无号，终有凶。</p><p>象曰：「无号」之「凶」，终不可长也。</p><p>解读</p><p>「夬扬于王庭」者，夬，决也。阳长至五，上六一柔而乘五刚，以人事喻，犹小人乘陵君子而为不顺，众共决之，故曰「夬」也。以刚决柔，以君子除小人，以刚正之德去邪謟，故可显然于王者之庭，发扬决断之事，示公正而无私隐，故曰「扬于王庭」。王庭亦公庭也。孚号有厉者，号，号令也；厉，危也。以刚正之德，而行孚信号令，施决断之事，即上六之柔，亦喻邪謟小人，忧危之理，分明可见矣。「告自邑，不利即戎」者，夫兴师动众，必扰国乱人，今上六一柔，既乘刚不顺，更喻小小之人要除，只可独行决断，不必更兴师旅，故「不利即戎」也。「利有攸往」者，刚德既长，柔邪必消，刚道既成，利有所往也。象曰：「泽上于天，夬」者，泽性流动，虽𫏐上天，必决而下，故取夬象。「君子以施禄及下，居德则忌」者，夫行决断之道，必威恩并行，若威而不恩，即过在苛暴，若恩而不威，即失于制断。君子行决之时，必须恩禄及于下人，又须居德于身，人则禀其威禁也，忌是禁也。</p><p>初九，壮于前趾，往不胜，为咎。趾，足也，处体最下。初九处决之首，欲行决断之事，必须审其事宜，量其可否，然后始行其令。今为刚健之初，所壮在于趾足，刚壮未全，往必不胜，先有咎生，故曰「往不胜为咎」也。</p><p>「九二，惕号，莫夜有戎，勿恤」者，惕，惧。号，呼也。九二以刚处中，刚则正直，中又不偏，而有此德，能行决断，虽有人惧呼来报云：至莫必有戎寇侵害。缘九二自恃中直，不枉刑断，虽闻此言，心无疑忧而惑，故曰「勿恤」也。</p><p>「九三，壮于𬱓，有凶，君子夬夬，独行遇雨若濡，有愠，无咎」者，𬱓，面颧也，谓上六也。上六居众阳之上，居而不安，若颧之处面。以九三刚阳而应上六，即是君子以助小人。𬱓之处面，谁人不见？故曰「壮于𬱓，有凶」也。剥卦以阴应阳为善，为阴柔须有所附。今九三以阳应阴，众欲决去，独往应之为凶。若达理君子，知小人不可与亲，而能舍其本应，决之不疑，故曰「君子夬夬」也。若独行殊志，应于小人，即有罪罚，如遇雨沾濡，徒怀忿恨，能无怨于人，即须「有愠无咎」也。</p><p>「九四：臀无肤，其行次且，牵羊悔亡，闻言不信」者，次且，行不前之貌也。羊，壮也。九四据下三阳，前进必见侵伤，犹如「臀无肤」，则居不得安，居不得安，行亦难进。然五阳当位，体又刚壮，四若牵系于五，身有所托，即不刚，不敢侵伤，故曰「牵羊悔亡」也。然四亦是刚阳，虽五有刚壮，未肯信服事五，故曰「闻言不信也」。</p><p>「九五：苋陆夬夬，中行无咎」者，苋陆，草之柔脆，谓上六也。以九五之刚，决上六之柔，决之至易，如决柔脆之物，故曰「苋陆夬夬」。以居尊位而亲决上六，即是以至尊而敌至卑，虽其克胜，不足为贵，但处位中行，才得免咎而已，故曰「中行无咎」也。</p><p>上六：无号，终有凶者，以柔乘刚而居众阳之上，其犹小人乘陵君子，凶危必至，故戒之曰：「不用号啕，终致凶也。」</p>',23)])])}const u=e(r,[["render",i]]);export{h as __pageData,u as default};
